#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "lu.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// -----------------------------------------------------------------------------
// Array initialization: translate Polybench init_array() into a Halide pipeline
// -----------------------------------------------------------------------------
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // We map the original C array A[i][j] to Halide buffer A(j, i):
    //   - i is the row index    -> second dimension (y)
    //   - j is the column index -> first dimension (x)

    Var i("i"), j("j");
    Func A0("A0"), B("B");

    // First, generate the lower-triangular matrix used as in the C code:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Note: for 0 <= j < n, (-j % n) == -j, so we can drop the % n.
    // We fold all this into a single expression:

    Expr one   = cast<num_t>(1);
    Expr zero  = cast<num_t>(0);
    Expr n_val = cast<num_t>(n);

    // A0(j, i) corresponds to C's A[i][j]
    A0(j, i) = select(
        j <= i,
        // On or below the diagonal
        select(i == j,
               // Diagonal element
               one,
               // Strictly lower triangular part
               cast<num_t>(-j) / n_val + one),
        // Above the diagonal
        zero);

    // Now make the matrix symmetric positive definite by computing:
    //
    // B[r][s] = sum_t A[r][t] * A[s][t];
    //
    // and then copying B back into A. In terms of our mapping:
    //   B(r, s) in C  -> B(j, i) in Halide
    //   A[r][t]       -> A0(t, r) -> A0(t, i)
    //   A[s][t]       -> A0(t, s) -> A0(t, j)
    //
    // So:
    //   B(j, i) = sum_{t=0..n-1} A0(t, i) * A0(t, j)

    RDom t(0, n, "t");
    B(j, i) = cast<num_t>(0);
    B(j, i) += A0(t, i) * A0(t, j);

    // -----------------------------
    // Schedule for SPD initialization
    // -----------------------------
    //
    // B is a dense N×N symmetric matrix multiply B = A0 * A0ᵀ.
    // We:
    //   - compute B at root once
    //   - parallelize across rows (i)
    //   - vectorize across the contiguous column dimension (j)
    // The reduction over t remains inner and sequential per element.

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Pure definition: zero-initialize B
    B.compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // Reduction update: accumulate along t
    B.update()
        .reorder(j, i, t)  // make j (contiguous) the innermost pure var
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize B directly into the provided buffer A.
    B.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Matrix A: original C is DATA_TYPE A[N][N];
    // We map to Halide Buffer with shape (cols, rows) = (n, n)
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A to a symmetric positive-definite matrix
    init_array(n, A);

    // -------------------------------------------------------------------------
    // Translate kernel_lu into Halide-assisted code.
    //
    // Original C kernel:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   for (j = i; j < n; j++) {
    //     for (k = 0; k < i; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //   }
    // }
    //
    // This algorithm has loop-carried dependencies along i and in the
    // lower-triangular j-loop, so we cannot express the full kernel as a
    // single pure Halide Func. Instead, we:
    //
    //   - Keep the outer loop over i and the lower-triangular loop over j
    //     on the host (they must remain strictly sequential).
    //
    //   - Implement the *upper* part j >= i as a Halide pipeline that,
    //     for a fixed i, computes the entire updated row A[i][j] for all
    //     j in a single realization. This pipeline:
    //        A[i][j] <- A[i][j] - sum_{k=0}^{i-1} A[i][k] * A[k][j]
    //
    //     can be safely parallelized and vectorized across j because all
    //     j >= i are independent once row i's lower-triangular part is done.
    //
    //   - We represent the current matrix A as an ImageParam so that
    //     Halide reads the latest values (L and U factors) produced by
    //     the host between realizations.
    // -------------------------------------------------------------------------

    // ImageParam representing the current matrix A; we never write
    // to A inside Halide; we only read from it. In-place updates to A
    // are done on the host after each realization.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Scalar parameter for the current row i
    Param<int> i_param("i");

    // Func to compute the updated U-row:
    //   row_u(j) = A[i][j] - sum_{k=0}^{i-1} A[i][k] * A[k][j]
    //
    // In terms of our mapping A[i][j] in C -> A(j, i) in Halide:
    //
    //   A[i][j]      -> A_param(j, i_param)
    //   A[i][k]      -> A_param(k, i_param)
    //   A[k][j]      -> A_param(j, k)
    //
    Var j("j");
    RDom k_u(0, i_param, "k_u");
    Func u_row("u_row");

    // Start from the current A[i][j]
    u_row(j) = A_param(j, i_param);

    // Subtract the dot-product sum_{k < i} A[i][k] * A[k][j]
    u_row(j) += cast<num_t>(-1) *
                A_param(k_u, i_param) *
                A_param(j, k_u);

    // -----------------------------
    // Schedule for the U-row update
    // -----------------------------
    //
    // For a fixed i, all j are independent, so we:
    //   - compute u_row at root once per i
    //   - tile j and parallelize across tiles
    //   - vectorize across the contiguous j sub-dimension
    // The reduction over k_u remains inner and sequential per (tile, j).

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    Var jo("jo"), ji("ji");

    u_row.compute_root()
        .split(j, jo, ji, 64)   // tiles of 64 columns
        .parallel(jo)           // parallel over tiles of j
        .vectorize(ji, vec_width);

    u_row.update()
        .reorder(j, k_u)        // make j the pure var innermost for vectorization
        .split(j, jo, ji, 64)
        .parallel(jo)
        .vectorize(ji, vec_width);

    // JIT-compile once; we will reuse for all rows i
    u_row.compile_jit(target);

    // Reusable buffer to hold the updated U-row for a given i
    Halide::Buffer<num_t> u_row_buf(n);

    // -------------------------------------------------------------------------
    // Run kernel and time it
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // ------------------------------
        // 1) Lower-triangular (L) part:
        //    j = 0 .. i-1 (sequential)
        // ------------------------------
        //
        // A[i][j] = (A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[k][j]) / A[j][j]
        //
        // Mapping to buffer A(j, i) (column-major in Halide sense, row-major
        // in the original C sense):
        //   A[i][j]  -> A(j, i)
        //   A[i][k]  -> A(k, i)
        //   A[k][j]  -> A(j, k)
        //
        for (int j = 0; j < i; j++) {
            num_t sum = (num_t)0;
            for (int k = 0; k < j; k++) {
                sum += A(k, i) * A(j, k);
            }

            num_t val = A(j, i) - sum;
            val /= A(j, j);  // pivot on the diagonal
            A(j, i) = val;
        }

        // ------------------------------
        // 2) Upper-triangular (U) part:
        //    j = i .. n-1, Halide row
        // ------------------------------
        //
        // For fixed i, all j >= i are independent given the completed L row,
        // so we use the u_row Func to compute the entire updated row A[i,*]
        // in one vectorized / parallel Halide realization.

        i_param.set(i);
        u_row.realize(u_row_buf);

        // Copy the updated upper row back into A in-place (only j >= i matter).
        for (int j = i; j < n; j++) {
            A(j, i) = u_row_buf(j);
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // A[i][j] in C corresponds to A(j, i) in Halide
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
