#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "lu.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// -----------------------------------------------------------------------------
// Array initialization: translate Polybench init_array() into a Halide pipeline
// -----------------------------------------------------------------------------
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // We map the original C array A[i][j] to Halide buffer A(j, i):
    //   - i is the row index    -> second dimension (y)
    //   - j is the column index -> first dimension (x)

    Var i("i"), j("j");
    Func A0("A0"), SPD("SPD");
    RDom t(0, n, "t");

    // A0 encodes the initial lower-triangular matrix from the Polybench code:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // For 0 <= j < n, (-j % n) == -j, so we can drop the modulus.
    // Mapping to Halide: A[i][j] -> A0(j, i).
    Expr one   = cast<num_t>(1);
    Expr zero  = cast<num_t>(0);
    Expr n_val = cast<num_t>(n);
    Expr j_f   = cast<num_t>(j);

    // On or below the diagonal:
    //   if j < i:  (-j)/n + 1
    //   if j == i: 1
    // Above the diagonal:
    //   0
    A0(j, i) = select(j < i,
                      -j_f / n_val + one,
                      select(j == i, one, zero));

    // Now form a symmetric positive-definite matrix:
    //
    // B[r][s] = sum_t A0[r][t] * A0[s][t]
    //
    // and then copy B back into A. In terms of our mapping:
    //   B(r, s) in C  -> SPD(j, i) in Halide
    //
    // We compute SPD directly into A: SPD(j, i) = sum_t A0(t, i) * A0(t, j)
    SPD(j, i) = cast<num_t>(0);
    SPD(j, i) += A0(t, i) * A0(t, j);

    // -------------------------------------------------------------------------
    // Schedule for SPD construction (A = A0 * A0ᵀ)
    //
    // This is an O(n^3) dense matrix–matrix product and dominates init time.
    // We:
    //   - tile (j, i) for cache locality
    //   - parallelize across row tiles
    //   - vectorize across the contiguous j dimension
    //   - split and unroll the reduction over t
    // -------------------------------------------------------------------------
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());

    Var jo("jo"), ji("ji"), io("io"), ii("ii");
    RVar to("to"), ti("ti");

    // Tile the output (j, i) domain.
    const int tile_x = 32;
    const int tile_y = 32;
    const int tile_t = 32;

    SPD.compute_root()
        .tile(j, i, jo, io, ji, ii, tile_x, tile_y)
        .reorder(ji, ii, jo, io)         // inner loops: ji (x), ii (y) for good locality
        .vectorize(ji, vec_width)        // SIMD across contiguous x
        .parallel(io);                   // parallelize across row tiles

    SPD.update()
        .tile(j, i, jo, io, ji, ii, tile_x, tile_y)
        .split(t, to, ti, tile_t)
        // Inner loop order: small chunk of t, then ji, then ii
        .reorder(ti, ji, ii, to, jo, io)
        .vectorize(ji, vec_width)
        .unroll(ti)
        .parallel(io);

    // Realize SPD directly into the provided buffer A.
    SPD.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Matrix A: original C is DATA_TYPE A[N][N];
    // We map to Halide Buffer with shape (cols, rows) = (n, n)
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A (SPD matrix)
    init_array(n, A);

    // -------------------------------------------------------------------------
    // Translate kernel_lu into Halide-assisted code.
    //
    // Original C kernel:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   for (j = i; j < n; j++) {
    //     for (k = 0; k < i; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //   }
    // }
    //
    // This algorithm has loop-carried dependencies along i and j, so we cannot
    // express the full kernel as a single pure Halide Func. We therefore keep
    // the outer control structure in C++ and use Halide only for the inner
    // reductions over k:
    //
    //   sum_{k<j} A[i][k] * A[k][j]
    //   sum_{k<i} A[i][k] * A[k][j]
    //
    // We use an ImageParam to read the current matrix A and Param<int> for the
    // indices i and j. For each (i, j), we realize a 1‑element Func that
    // computes the corresponding dot product. This preserves the sequential
    // LU dependencies while still vectorizing the heavy inner products.
    // -------------------------------------------------------------------------

    // ImageParam representing the current matrix A; we only read from A inside
    // the Halide Funcs below. In-place updates to A are done on the host and
    // are visible to Halide via the shared underlying buffer.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Scalar parameters for the current (i, j) indices
    Param<int> i_param("i");
    Param<int> j_param("j");

    // Dummy spatial variable for scalar outputs; we use a 1‑element Buffer
    // and ignore this coordinate. This lets us reuse a preallocated buffer
    // instead of allocating a new scalar Buffer for every realization.
    Var d("d");

    // Func to compute A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[k][j]
    // for the case j < i (the "L" part), before dividing by A[j][j].
    Func left_elem("left_elem");
    {
        // A[i][j] in C corresponds to A_param(j_param, i_param) in Halide.
        left_elem(d) = A_param(j_param, i_param);

        // Sum over k = 0 .. j-1:
        //   A[i][j] -= A[i][k] * A[k][j]
        //
        // A[i][k] -> A_param(k, i_param)
        // A[k][j] -> A_param(j_param, k)
        RDom k_left(0, j_param, "k_left");
        left_elem(d) += cast<num_t>(-1) *
                        A_param(k_left, i_param) *
                        A_param(j_param, k_left);
    }

    // Func to compute A[i][j] - sum_{k=0}^{i-1} A[i][k] * A[k][j]
    // for the case j >= i (the "U" part).
    Func right_elem("right_elem");
    {
        right_elem(d) = A_param(j_param, i_param);

        // Sum over k = 0 .. i-1:
        //   A[i][j] -= A[i][k] * A[k][j]
        RDom k_right(0, i_param, "k_right");
        right_elem(d) += cast<num_t>(-1) *
                         A_param(k_right, i_param) *
                         A_param(j_param, k_right);
    }

    // -------------------------------------------------------------------------
    // Schedule the LU helper Funcs.
    //
    // We JIT compile them once and reuse for all (i, j). The key optimization
    // is to vectorize the reduction over k, which is the dominant cost for
    // each scalar LU update.
    // -------------------------------------------------------------------------
    Target target = get_host_target();
    int vec_lu = target.natural_vector_size(type_of<num_t>());

    {
        // Extract the reduction RVars by name so we can schedule them.
        // (They were named "k_left" and "k_right" above.)
        RVar k_left = left_elem.update(0).rvars()[0];
        left_elem
            .compute_root()                 // single scalar result per realize
            .bound(d, 0, 1);                // 1D of length 1
        left_elem.update(0)
            .vectorize(k_left, vec_lu);     // SIMD over k in L-part
    }

    {
        RVar k_right = right_elem.update(0).rvars()[0];
        right_elem
            .compute_root()
            .bound(d, 0, 1);
        right_elem.update(0)
            .vectorize(k_right, vec_lu);    // SIMD over k in U-part
    }

    // JIT-compile the scalar pipelines once; we will reuse them for all (i, j).
    left_elem.compile_jit(target);
    right_elem.compile_jit(target);

    // Preallocate 1-element buffers to avoid reallocation on every realize
    Halide::Buffer<num_t> tmp_left(1);
    Halide::Buffer<num_t> tmp_right(1);

    // -------------------------------------------------------------------------
    // Run kernel and time it
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // First inner loop: j = 0 .. i-1  (L-part)
        for (int j = 0; j < i; j++) {
            i_param.set(i);
            j_param.set(j);

            // Compute A[i][j] - sum_{k<j} A[i][k] * A[k][j]
            left_elem.realize(tmp_left);
            num_t val = tmp_left(0);  // 1-element buffer

            // Divide by A[j][j]
            // Mapping: A[j][j] in C -> A(j, j) in Halide
            val /= A(j, j);

            // Store back into A[i][j] (i.e. A(j, i) in Halide)
            A(j, i) = val;
        }

        // Second inner loop: j = i .. n-1  (U-part)
        for (int j = i; j < n; j++) {
            i_param.set(i);
            j_param.set(j);

            // Compute A[i][j] - sum_{k<i} A[i][k] * A[k][j]
            right_elem.realize(tmp_right);
            num_t val = tmp_right(0);  // 1-element buffer

            // Store back into A[i][j] (no division here)
            A(j, i) = val;
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // A[i][j] in C corresponds to A(j, i) in Halide
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
