// include common definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "lu.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// -----------------------------------------------------------------------------
// Array initialization: translate Polybench init_array() into a Halide pipeline
// -----------------------------------------------------------------------------
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // We map the original C array A[i][j] to Halide buffer A(j, i):
    //   - i is the row index  -> second dimension (y)
    //   - j is the column index -> first dimension (x)

    Var x("x"), y("y");   // x == column j, y == row i
    Func A0("A0"), B("B");

    // First, generate the lower-triangular matrix used as in the C code:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Note: for 0 <= j < n, (-j % n) == -j, so we can drop the % n.

    Expr one   = cast<num_t>(1);
    Expr zero  = cast<num_t>(0);
    Expr n_val = cast<num_t>(n);

    // A0(j, i) corresponds to A[i][j] in the C reference.
    A0(x, y) = select(
        x <= y,
        // On or below the diagonal
        select(y == x,
               // Diagonal element
               one,
               // Strictly lower triangular part
               cast<num_t>(-x) / n_val + one),
        // Above the diagonal
        zero);

    // Now make the matrix positive semi-definite by computing:
    //
    // B[r][s] = sum_t A[r][t] * A[s][t];
    //
    // Mapping into Halide coordinates:
    //   r -> y, s -> x, t -> t
    //   B(x, y) = sum_{t=0..n-1} A0(t, y) * A0(t, x)

    RDom t(0, n, "t");
    B(x, y) = cast<num_t>(0);
    B(x, y) += A0(t, y) * A0(t, x);

    // --------------------------
    // Scheduling for init stage
    // --------------------------
    //
    // This is effectively a dense matrix-multiply (Gram product).
    // We:
    //   - parallelize across rows (y)
    //   - vectorize across contiguous columns (x)
    //   - do the same for the reduction update.

    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tile size for the output matrix; small enough to fit in cache.
    const int tile_x = 32;
    const int tile_y = 32;

    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

    // Pure definition (initialization to zero)
    B.compute_root()
        .tile(x, y, xo, yo, xi, yi, tile_x, tile_y)
        .parallel(yo)          // parallelize over row tiles
        .vectorize(xi, vec_width);

    // Reduction update
    B.update()
        .tile(x, y, xo, yo, xi, yi, tile_x, tile_y)
        // Order loops from innermost to outermost: xi, yi, t, xo, yo
        // so that xi (columns inside a tile) is innermost and vectorized.
        .reorder(xi, yi, t, xo, yo)
        .parallel(yo)
        .vectorize(xi, vec_width);

    // Compile once and realize into the provided buffer A.
    B.compile_jit(target);
    B.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Matrix A: original C is DATA_TYPE A[N][N];
    // We map to Halide Buffer with shape (cols, rows) = (n, n)
    // Access pattern: A(j, i) == C A[i][j].
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A to a symmetric positive-definite matrix
    init_array(n, A);

    // -------------------------------------------------------------------------
    // Translate kernel_lu into Halide-assisted code.
    //
    // Original C kernel:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   for (j = i; j < n; j++) {
    //     for (k = 0; k < i; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //   }
    // }
    //
    // This algorithm has loop-carried dependencies along i and across j in the
    // first (L) loop, so we cannot express the full kernel as one pure Func.
    //
    // Strategy (respecting dependencies):
    //   - Keep the outer loop over i on the host.
    //   - Keep the first inner loop (j < i, L-part) as a host loop and use
    //     a scalar Halide reduction over k to compute each A[i][j] update.
    //   - For the second inner loop (j >= i, U-part), where all j are
    //     independent for a fixed i, use a *vectorized and parallel* Halide
    //     pipeline that updates the entire row segment j = i..n-1 at once.
    // -------------------------------------------------------------------------

    // ImageParam representing the current matrix A; note that we never write
    // to A inside Halide; we only read from it in the Funcs below. The
    // in-place updates to A are done on the host after each realization.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Scalar parameters for the current row/column indices
    Param<int> i_param("i");
    Param<int> j_param("j");

    // ----------------------------
    // L-part: j < i (scalar Func)
    // ----------------------------
    //
    // Compute:
    //   tmp_L = A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[k][j]
    // Then the host divides by A[j][j] and writes back into A[i][j].
    //
    // Mapping to Halide indices:
    //   A[i][j]   -> A_param(j_param, i_param)
    //   A[i][k]   -> A_param(k,       i_param)
    //   A[k][j]   -> A_param(j_param, k)
    Func left_elem("left_elem");
    {
        left_elem() = A_param(j_param, i_param);

        RDom k_left(0, j_param, "k_left");
        left_elem() += cast<num_t>(-1) *
                       A_param(k_left, i_param) *
                       A_param(j_param, k_left);
    }

    // ----------------------------
    // U-part: j >= i (row Func)
    // ----------------------------
    //
    // For fixed i, all j in [i, n) are independent once L-row i has been
    // computed, so we can update the whole row in one vectorized/parallel
    // Halide call:
    //
    //   for j = i..n-1:
    //     A[i][j] -= sum_{k=0}^{i-1} A[i][k] * A[k][j];
    //
    // Mapping to Halide indices:
    //   A[i][j]   -> A_param(j,      i_param)
    //   A[i][k]   -> A_param(k,      i_param)
    //   A[k][j]   -> A_param(j,      k)
    //
    // We parameterize j as:
    //   j = i_param + j_rel, where j_rel = 0..(n-i-1).
    Var j_rel("j_rel");
    Func u_row("u_row");

    // Actual column index j = i_param + j_rel
    Expr j_col = j_rel + i_param;

    // Pure definition: starting value A[i][j]
    u_row(j_rel) = A_param(j_col, i_param);

    // Reduction over k = 0..i-1: accumulate -A[i][k] * A[k][j]
    RDom k_u(0, i_param, "k_u");
    u_row(j_rel) += cast<num_t>(-1) *
                    A_param(k_u, i_param) *
                    A_param(j_col, k_u);

    // ----------------------------
    // Scheduling for LU pipelines
    // ----------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Schedule for scalar L-part reduction:
    //
    // left_elem is scalar-valued, but we can still vectorize the reduction
    // over k_left to improve throughput of the dot-product.
    {
        RVar k_left_r = k_left;  // alias to schedule on

        left_elem.compute_root();
        left_elem.update()
                 .vectorize(k_left_r, vec_width);
    }

    // Schedule for U-row pipeline:
    //
    // u_row is 1D over j_rel. We tile j_rel so that:
    //   - outer tile index jo is parallelized across threads;
    //   - inner index ji is vectorized.
    {
        Var jo("jo"), ji("ji");
        const int tile_j = 64;  // a reasonable cache-friendly row tile

        u_row.compute_root();

        // Pure definition
        u_row.split(j_rel, jo, ji, tile_j)
             .parallel(jo)
             .vectorize(ji, vec_width);

        // Reduction update
        u_row.update()
             .split(j_rel, jo, ji, tile_j)
             // Inner to outer: ji (vectorized), k_u, jo (parallelized)
             .reorder(ji, k_u, jo)
             .parallel(jo)
             .vectorize(ji, vec_width);
    }

    // JIT-compile the scalar and row pipelines once; we will reuse them
    // for all (i, j).
    left_elem.compile_jit(target);
    u_row.compile_jit(target);

    // -------------------------------------------------------------------------
    // Run kernel and time it (LU factorization only)
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Temporary buffer for the U-row updates: length n, reused for every i.
    Halide::Buffer<num_t> u_temp(n);
    u_temp.set_min(0);

    for (int i = 0; i < n; i++) {
        // -------------------------
        // L-part: j = 0 .. i-1
        // -------------------------
        for (int j = 0; j < i; j++) {
            i_param.set(i);
            j_param.set(j);

            // Compute A[i][j] - sum_{k<j} A[i][k] * A[k][j]
            Halide::Buffer<num_t> tmp = left_elem.realize();
            num_t val = tmp();  // zero-dimensional buffer

            // Divide by A[j][j]
            // Mapping: A[j][j] in C -> A(j, j) in Halide
            val /= A(j, j);

            // Store back into A[i][j] (i.e. A(j, i) in Halide)
            A(j, i) = val;
        }

        // -------------------------
        // U-part: j = i .. n-1
        // -------------------------
        //
        // Now that the entire L-row i has been computed, all columns j >= i
        // are independent, so we process them in one Halide call.
        i_param.set(i);

        int row_len = n - i;  // number of columns j in [i, n)

        // Create a cropped view of u_temp for the active length.
        Halide::Buffer<num_t> u_row_buf = u_temp.cropped(0, row_len);

        // Compute updated A[i][j] for all j in [i, n) into u_row_buf.
        u_row.realize(u_row_buf);

        // Copy results back into A:
        //   A[i][j] in C -> A(j, i) in Halide
        for (int offset = 0; offset < row_len; ++offset) {
            int j = i + offset;
            A(j, i) = u_row_buf(offset);
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // A[i][j] in C corresponds to A(j, i) in Halide
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
