#include "lu.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// -----------------------------------------------------------------------------
// Array initialization: optimized Halide pipeline for Polybench init_array()
// -----------------------------------------------------------------------------
//
// Semantics (original C):
//
//   /* lower-triangular A0 */
//   for (i = 0; i < n; i++) {
//     for (j = 0; j <= i; j++)
//       A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
//     for (j = i+1; j < n; j++)
//       A[i][j] = 0;
//     A[i][i] = 1;
//   }
//
//   /* make it SPD: A = A0 * A0ᵀ */
//   for (r = 0; r < n; r++)
//     for (s = 0; s < n; s++) {
//       B[r][s] = 0;
//       for (t = 0; t < n; t++)
//         B[r][s] += A0[r][t] * A0[s][t];
//     }
//   for (r,s) A[r][s] = B[r][s];
//
// Mapping to Halide Buffer:
//   C's A[i][j]  <->  Halide Buffer A(j, i)
//   (x = column j, y = row i; x is contiguous in memory)
// -----------------------------------------------------------------------------
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // Vars use Halide coordinates: j = x (column), i = y (row)
    Var i("i"), j("j");
    Func A0("A0"), B("B");

    Expr one  = cast<num_t>(1);
    Expr zero = cast<num_t>(0);
    Expr n_val = cast<num_t>(n);

    // -------------------------------------------------------------------------
    // Stage 1: pure lower-triangular A0(j, i)
    //
    // For 0 <= j < n, (-j % n) == -j, so we drop the modulus.
    //
    //   if (j < i) : A0[i][j] = (-j)/n + 1
    //   if (j = i) : A0[i][i] = 1
    //   if (j > i) : A0[i][j] = 0
    //
    // In Halide index order: A0(j, i).
    // -------------------------------------------------------------------------
    A0(j, i) = select(
        j <= i,
        // on or below the diagonal
        select(i == j,
               one,                         // diagonal element
               cast<num_t>(-j) / n_val + one),
        // strictly above the diagonal
        zero);

    // -------------------------------------------------------------------------
    // Stage 2: SPD product B = A0 * A0ᵀ
    //
    // In C notation:
    //   B[r][s] = sum_t A0[r][t] * A0[s][t]
    //
    // With our mapping:
    //   B(j, i) corresponds to B[i][j]
    //   A0[r][t] -> A0(t, r) -> A0(t, i)
    //   A0[s][t] -> A0(t, s) -> A0(t, j)
    //
    // So:
    //   B(j, i) = Σ_t A0(t, i) * A0(t, j)
    //
    // We realize B directly into the provided Buffer A. This is equivalent
    // to computing B and then copying B into A.
    // -------------------------------------------------------------------------
    RDom t(0, n, "t");
    B(j, i) = cast<num_t>(0);
    B(j, i) += A0(t, i) * A0(t, j);

    // -------------------------------------------------------------------------
    // Scheduling for good locality and parallelism
    //
    // - A0 is a simple triangular initializer; we compute it once, in
    //   parallel over rows and vectorized across columns.
    // - B is a dense n×n SPD product (dominant O(n³) work). We parallelize
    //   across rows (i) and vectorize across contiguous columns (j); the
    //   reduction over t is kept innermost after reordering.
    // -------------------------------------------------------------------------
    Target host_target = get_host_target();
    const int vec_width = host_target.natural_vector_size(type_of<num_t>());

    // A0 is pure: compute once into an intermediate buffer.
    A0.compute_root()
        .parallel(i)          // parallel over rows
        .vectorize(j, vec_width); // SIMD across contiguous columns

    // Initialize B(j,i) = 0 and then accumulate over t.
    B.compute_root()
        .parallel(i)          // each row of B is independent
        .vectorize(j, vec_width);

    // Schedule the reduction step: make 'j' innermost and vectorized, 'i'
    // outer and parallel; iterate t in the middle.
    B.update()
        .reorder(j, t, i)     // for (i) for (t) for (j)
        .parallel(i)
        .vectorize(j, vec_width);

    // Run the initialization pipeline.
    B.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Matrix A: original C is DATA_TYPE A[N][N];
    // We map to Halide Buffer with shape (cols, rows) = (n, n)
    // C's A[i][j] <-> A(j, i)
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A as a symmetric positive-definite matrix
    init_array(n, A);

    // -------------------------------------------------------------------------
    // LU factorization kernel (Polybench kernel_lu)
    //
    // Original C kernel:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   for (j = i; j < n; j++) {
    //     for (k = 0; k < i; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //   }
    // }
    //
    // This algorithm has true loop-carried dependencies along i and j:
    //   - row i depends on all rows < i,
    //   - within row i, lower part j < i depends on A[i,k] for k < j.
    //
    // Halide's reduction model does not allow expressing these triangular
    // dependencies in a single pure Func. Following the recommended pattern
    // for such algorithms, we:
    //
    //   * Keep the outer loops over i and j on the host to preserve the
    //     sequential dependency structure.
    //   * Use small Halide reduction pipelines to compute the inner
    //     dot-products over k:
    //         sum_{k<j} A[i][k] * A[k][j]
    //         sum_{k<i} A[i][k] * A[k][j]
    //     These are expressed with ImageParam + Param<int> and realized
    //     as scalars.
    //
    // This respects all dependencies while still using Halide to SIMD‑ize
    // and optimize the most arithmetic-heavy inner reductions.
    // -------------------------------------------------------------------------

    // ImageParam representing the current matrix A; we never write to A
    // inside Halide, only read. The host performs the in-place updates.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Scalar parameters for the current (i, j) indices
    Param<int> i_param("i");
    Param<int> j_param("j");

    // ---------------------------------------------------------------------
    // Func for L-part:
    //
    //   left_elem() = A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[k][j]
    //
    // in C indexing. Using our mapping A[i][j] <-> A_param(j, i),
    // this becomes:
    //
    //   left_elem() = A_param(j_param, i_param)
    //                 - Σ_{k=0}^{j_param-1}
    //                      A_param(k, i_param) * A_param(j_param, k)
    //
    // left_elem is a 0-D Func (scalar).
    // ---------------------------------------------------------------------
    Func left_elem("left_elem");
    {
        // Base value: A[i][j]
        left_elem() = A_param(j_param, i_param);

        // Reduction over k = 0 .. j-1:
        RDom k_left(0, j_param, "k_left");
        left_elem() += cast<num_t>(-1) *
                       A_param(k_left, i_param) *
                       A_param(j_param, k_left);
        // Note: We keep the schedule of this small reduction default;
        // the work per call grows with j and is dominated by arithmetic.
    }

    // ---------------------------------------------------------------------
    // Func for U-part:
    //
    //   right_elem() = A[i][j] - sum_{k=0}^{i-1} A[i][k] * A[k][j]
    //
    // in C indexing. With A[i][j] <-> A_param(j, i),
    //
    //   right_elem() = A_param(j_param, i_param)
    //                  - Σ_{k=0}^{i_param-1}
    //                       A_param(k, i_param) * A_param(j_param, k)
    //
    // again as a 0-D Func.
    // ---------------------------------------------------------------------
    Func right_elem("right_elem");
    {
        right_elem() = A_param(j_param, i_param);

        RDom k_right(0, i_param, "k_right");
        right_elem() += cast<num_t>(-1) *
                        A_param(k_right, i_param) *
                        A_param(j_param, k_right);
    }

    // JIT-compile the scalar pipelines once; we will reuse them for all (i, j).
    left_elem.compile_jit();
    right_elem.compile_jit();

    // -------------------------------------------------------------------------
    // Run kernel and time it
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // First inner loop: j = 0 .. i-1  (L-part)
        for (int j = 0; j < i; j++) {
            i_param.set(i);
            j_param.set(j);

            // Compute A[i][j] - sum_{k<j} A[i][k] * A[k][j]
            Halide::Buffer<num_t> tmp = left_elem.realize();
            num_t val = tmp();  // zero-dimensional buffer

            // Divide by A[j][j]:
            // C's A[j][j] -> A(j, j) in Halide coordinates.
            val /= A(j, j);

            // Store back into A[i][j] (C indexing), i.e. A(j, i) in Halide.
            A(j, i) = val;
        }

        // Second inner loop: j = i .. n-1  (U-part)
        for (int j = i; j < n; j++) {
            i_param.set(i);
            j_param.set(j);

            // Compute A[i][j] - sum_{k<i} A[i][k] * A[k][j]
            Halide::Buffer<num_t> tmp = right_elem.realize();
            num_t val = tmp();  // zero-dimensional buffer

            // Store back into A[i][j] (no division here)
            A(j, i) = val;
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // C's A[i][j] corresponds to A(j, i) in Halide
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
